package main

import (
	"fmt"
	"os"
	"path/filepath"
	"strings"

	"kintsugi/internal/blueprints"
)

// cmdNew scaffolds a project from a blueprint (DESIGN §6.2):
//
//	kintsugi new                          list the blueprints
//	kintsugi new list                     list the blueprints
//	kintsugi new <blueprint> <dir> [--force]
//
// The scaffold is a plain file copy with the project token substituted; nothing
// is generated by a model, and the Authorization & scope section lands as an
// operator placeholder by construction.
func cmdNew(ws string, args []string) {
	if len(args) == 0 || args[0] == "list" || args[0] == "ls" {
		printBlueprints()
		return
	}

	// Flags may appear anywhere: scan positionally instead of using flag.Parse,
	// which stops at the first non-flag argument.
	force := false
	var pos []string
	for _, a := range args {
		switch {
		case a == "--force" || a == "-force" || a == "-f":
			force = true
		case strings.HasPrefix(a, "-") && a != "-":
			fmt.Fprintf(os.Stderr, "unknown flag %q\n\n", a)
			printBlueprintUsage()
			os.Exit(2)
		default:
			pos = append(pos, a)
		}
	}

	if len(pos) == 0 {
		printBlueprints()
		return
	}
	if len(pos) < 2 {
		printBlueprintUsage()
		os.Exit(2)
	}

	name, dir := pos[0], pos[1]
	// A relative directory resolves against the workspace, like every other
	// path the CLI takes.
	target := dir
	if !filepath.IsAbs(target) {
		target = filepath.Join(ws, dir)
	}
	abs, err := filepath.Abs(target)
	if err != nil {
		fail("new: %v", err)
	}
	project := filepath.Base(abs)

	bp, ok := blueprints.Lookup(name)
	if !ok {
		fail("new: unknown blueprint %q (valid: %s)", name, strings.Join(blueprints.Names(), ", "))
	}

	fmt.Printf("kintsugi new · %s · %s\n\n", bp.Name, abs)
	fmt.Printf("blueprint %s\n", bp.Summary)

	written, skipped, err := blueprints.Render(name, abs, project, force)
	if err != nil {
		fail("new: %v", err)
	}
	if len(written) > 0 {
		fmt.Printf("wrote     %s\n", strings.Join(written, ", "))
	} else {
		fmt.Println("wrote     (nothing)")
	}
	if len(skipped) > 0 {
		fmt.Printf("skipped   %s — already present, left untouched (pass --force to overwrite)\n",
			strings.Join(skipped, ", "))
	}

	fmt.Println()
	fmt.Println("Next: complete the Authorization & scope section yourself — the harness never writes it,")
	fmt.Println("      then run `kintsugi context show` to see the sections the model will actually read.")
}

// printBlueprints prints the blueprint table.
func printBlueprints() {
	list := blueprints.List()
	fmt.Println("kintsugi new — project blueprints")
	fmt.Println()
	fmt.Printf("  %-9s %s\n", "BLUEPRINT", "SCAFFOLDS")
	for _, b := range list {
		fmt.Printf("  %-9s %s\n", b.Name, fit(b.Summary, 96))
	}
	fmt.Println()
	printBlueprintUsage()
}

func printBlueprintUsage() {
	fmt.Print(`usage: kintsugi new <blueprint> <dir> [--force]

  kintsugi new list                 list the blueprints
  kintsugi new c2     <dir>         tasking client/server harness (lab fixtures)
  kintsugi new recon  <dir>         discovery/scan utility with lab-safe defaults

--force overwrites files the blueprint would otherwise leave untouched.
`)
}
